  str_season_mission_desc_8001001 = "Naquele momento, uma súbita explosão de batidas apressadas ecoou pelo ar, despertando Eve de seu estranho e fantástico sonho...",
  str_season_mission_desc_8001002 = "Naquele momento, uma súbita explosão de batidas apressadas ecoou pelo ar, despertando Eve de seu estranho e fantástico sonho...",
  str_season_mission_desc_8001003 = "Quem poderia ser essa sombra enigmática e o que a leva a destruir o precioso caderno de esboços de Eve?",
  str_season_mission_desc_8001004 = "Quem poderia ser essa sombra enigmática e o que a leva a destruir o precioso caderno de esboços de Eve?",
  str_season_mission_desc_8001005 = "O que faz a sombra fugir? Quanto mais ela corre, mais forte se torna o impulso de Eve em persegui-la e desvendar o mistério.",
  str_season_mission_desc_8001006 = "O que faz a sombra fugir? Quanto mais ela corre, mais forte se torna o impulso de Eve em persegui-la e desvendar o mistério.",
  str_season_mission_desc_8001007 = "Droga! A sombra conseguiu se esgueirar por um beco estreito! Não vou deixar que ela escape assim!",
  str_season_mission_desc_8001008 = "Droga! A sombra conseguiu entrar em um beco estreito! Não vou deixar que ela escape assim!",
  str_season_mission_desc_8001009 = "Finalmente, Eve alcançou a sombra no final do beco estreito, apenas para revelar que a sombra era, na verdade...",
  str_season_mission_desc_8001010 = "Finalmente, Eve alcançou a sombra no fim do beco estreito, apenas para revelar que a sombra era, na verdade...",
  str_season_mission_desc_8001011 = "Após suas ocupadas empreitadas, a sedenta Eve foi até o poço para beber água, mas percebeu algo peculiar ao redor.",
  str_season_mission_desc_8001012 = "Após seus esforços ocupados, a sedenta Eve foi até o poço para beber água, mas percebeu algo peculiar no ambiente.",
  str_season_mission_desc_8001013 = "Eve levantou a cabeça, suspirando com o clima do dia, apenas para avistar algo desconhecido por perto...",
  str_season_mission_desc_8001014 = "Eve levantou a cabeça, suspirando com o clima do dia, apenas para avistar algo desconhecido por perto...",
  str_season_mission_desc_8001015 = "Eve lutou para se livrar do grande cão ruivo, mas assim que chegou à entrada da Rua Cauda, ouviu gritos urgentes das pessoas ao seu redor...",
  str_season_mission_desc_8001016 = "Eve lutou para se livrar do grande cão ruivo, mas assim que chegou à entrada da Rua Cauda, ouviu gritos urgentes das pessoas ao seu redor...",
  str_season_mission_desc_8001017 = "Naquele momento, Eve não teve escolha a não ser seguir os passos de outro \"Eve\", aventurando-se mais fundo na Rua Cauda.",
  str_season_mission_desc_8001018 = "Naquele momento, Eve não teve escolha a não ser seguir os passos de outro \"Eve\", aventurando-se mais fundo na Rua Cauda.",
  str_season_mission_desc_8001019 = "Por que haveria outro \"eu\" neste mundo? A mente de Eve estava em turbulhão, cheia de confusão e desordem.",
  str_season_mission_desc_8001020 = "Por que haveria outro \"eu\" neste mundo? A mente de Eve estava em turbulhão, cheia de confusão e desordem.",
  str_season_mission_desc_8001021 = "Nas profundezas da Rua Cauda, existe um quarto que Eve nunca encontrou antes, e dentro dele, uma garota parece estar presa...?",
  str_season_mission_desc_8001022 = "Nas profundezas da Rua Cauda, existe um quarto que Eve nunca encontrou antes, e dentro dele, uma garota parece estar presa...?",
  str_season_mission_desc_8001023 = "Eve nunca havia considerado deixar sua pacata casinha, mas agora ela se depara com uma decisão que não pode evitar.",
  str_season_mission_desc_8001024 = "Eve nunca havia considerado deixar sua tranquila casinha, mas agora ela se depara com uma decisão que não pode evitar.",
  str_season_mission_desc_8001025 = "Conforme ela caminhava, Eve perdeu a noção de quão longe havia chegado, e o ar ficou ainda mais seco e quente do que o escaldante Deserto Rediesel...",
  str_season_mission_desc_8001026 = "Conforme ela caminhava, Eve perdeu a noção de quão longe havia chegado, e o ar ficou ainda mais seco e quente do que o escaldante Deserto Rediesel...",
  str_season_mission_desc_8001027 = "O caminho que \"Eve\" apontou não é apenas difícil, mas também assombrado por Eclipsitas. Eve hesita, sem saber se deve continuar avançando.",
  str_season_mission_desc_8001028 = "O caminho que \"Eve\" apontou não é apenas difícil, mas também assombrado por Eclipsitas. Eve hesita, sem saber se deve continuar avançando.",
