  str_season_mission_desc_8001030 = "Com a decisão tomada, Eve avança com a cabeça erguida e cheia de orgulho!",
  str_season_mission_desc_8001031 = "Fique atento à lava escaldante borbulhando bem ao lado dos seus pés no leito do rio. Não caia!",
  str_season_mission_desc_8001032 = "Fique atento à lava escaldante borbulhando bem ao lado dos seus pés no leito do rio. Não caia!",
  str_season_mission_desc_8001033 = "Eve avistou \"Eve\" à distância... Será que a resposta suprema está esperando lá?",
  str_season_mission_desc_8001034 = "Eve avistou \"Eve\" à distância... Será que a resposta suprema estaria esperando lá?",
