  str_season_treasure_bubble_info_1_1 = "O que está acontecendo comigo? Minha cabeça está girando...\nMas espere... tem alguém aqui?",
  str_season_treasure_bubble_info_2_1 = "Descobri o primeiro pedaço dos fragmentos do caderno de esboços!\nMas quando tentei juntá-lo, não pareceu se encaixar... Será que este está errado?",
  str_season_treasure_bubble_info_3_1 = "Outro fragmento. Um vaso vazio. Preciso encontrar a coisa certa para plantar nele para uma colheita...",
  str_season_treasure_bubble_info_4_1 = "A sombra deveria caber aqui?\nAh! Está do outro lado!",
  str_season_treasure_bubble_info_5_1 = "Ufa! Como essa xícara de chá veio parar aqui?\nAgora que a água foi buscada, eu realmente quero experimentar fazer um chá preto.",
  str_season_treasure_bubble_info_6_1 = [[
Trombei com uma criatura ultra-rara!
O destino deve ter nos guiado para cruzar nossos caminhos.]],
  str_season_treasure_bubble_info_7_1 = "O sabor nostálgico e familiar...",
  str_season_treasure_bubble_info_11_1 = "Segurá-lo me traz tanto conforto. Mayserá útil na minha jornada.",
  str_season_treasure_bubble_info_12_1 = "Espere, quem estava me chamando agora mesmo...?",
  str_season_treasure_bubble_info_14_1 = "Encontrei outro fragmento de caderno de esboços!",
  str_season_treasure_bubble_info_15_1 = "Eu preciso proteger esta semente!\nPreciso encontrar o local perfeito para plantá-la!",
  str_season_treasure_bubble_info_16_1 = "Tão linda, tão livre...",
  str_season_mission_bubble_info_2_1 = "Essa sombra pode invocar Eclipsitas?\nAgora eu não posso simplesmente ignorar isso, posso?",
  str_season_mission_bubble_info_4_1 = "Ei, espera! Não fuja!",
  str_season_mission_bubble_info_9_1 = "Onde... ela está me levando?",
  str_season_mission_bubble_info_10_1 = "Ela está logo à frente e parece que está esperando eu me aproximar?",
  str_season_gear_bubble_info_1_1 = "O caminho está bloqueado pela porta...\nAquilo no final da Rua Cauda pode ser útil!",
  str_season_gear_bubble_info_1_2 = "O que nos espera... aonde isso nos leva?",
